import java.util.*;
import java.io.*;
public class cf1342e{
    static int MOD = 998244353;

    public static void main(String[] args) throws IOException {
        PrintWriter out = new PrintWriter(new BufferedWriter(new OutputStreamWriter(System.out)));
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int n = Integer.parseInt(st.nextToken());
        long k = Long.parseLong(st.nextToken());
        if (k > n) {
            out.println(0);
            out.close();
            return;
        }
        int a1 = n - (int) k;
        long[] fact = new long[n + 1];
        long[] invFact = new long[n + 1];
        fact[0] = 1;
        for (int i = 1; i <= n; i++) {
            fact[i] = fact[i - 1] * i % MOD;
        }
        invFact[n] = fexp(fact[n], MOD - 2);
        for (int i = n - 1; i >= 0; i--) {
            invFact[i] = invFact[i + 1] * (i + 1) % MOD;
        }
        long sum = 0;
        for (int j = 0; j < a1; j++) {
            long term = fact[a1] * invFact[j] % MOD * invFact[a1 - j] % MOD;
            term = term * fexp(a1 - j, n) % MOD;
            if ((j & 1) == 1) term = MOD - term;
            sum = (sum + term) % MOD;
        }
        int a2 = Math.max(a1, (int) k);
        long comb = fact[n] * invFact[a2] % MOD * invFact[n - a2] % MOD;
        long ans = sum * comb % MOD;
        if (k != 0) {
            ans = ans * 2 % MOD;
        }
        out.println(ans);
        out.close();
    }

    public static long fexp(long a, long e) {
        long res = 1;
        while (e > 0) {
            if ((e & 1) == 1) res = res * a % MOD;
            a = a * a % MOD;
            e >>= 1;
        }
        return res;
    }
}
